if (document.getElementById('globo-filter-panel')) return;

// --- Inject styles ---
const style = document.createElement('style');
style.id = 'globo-filter-styles';
style.textContent = `
  #globo-filter-btn {
    position: fixed;
    bottom: 28px;
    right: 28px;
    z-index: 99999;
    background: #1a1a2e;
    color: #fff;
    border: none;
    border-radius: 50px;
    padding: 11px 20px;
    font-size: 14px;
    font-weight: 700;
    font-family: sans-serif;
    cursor: pointer;
    box-shadow: 0 4px 18px rgba(0,0,0,0.35);
    display: flex;
    align-items: center;
    gap: 8px;
    letter-spacing: 0.3px;
    transition: background 0.18s;
  }
  #globo-filter-btn:hover { background: #16213e; }
