  #globo-filter-panel {
    position: fixed;
    bottom: 80px;
    right: 28px;
    z-index: 99998;
    background: #fff;
    border-radius: 14px;
    box-shadow: 0 8px 40px rgba(0,0,0,0.22);
    width: 290px;
    font-family: sans-serif;
    overflow: hidden;
    display: none;
    flex-direction: column;
  }
  #globo-filter-panel.open { display: flex; }

  #globo-filter-panel .gfp-header {
    background: #1a1a2e;
    color: #fff;
    padding: 14px 18px 12px;
    font-size: 15px;
    font-weight: 700;
    letter-spacing: 0.2px;
    display: flex;
    align-items: center;
    gap: 8px;
  }
  #globo-filter-panel .gfp-header span { flex: 1; }
  #globo-filter-panel .gfp-header small {
    font-size: 11px;
    font-weight: 400;
    opacity: 0.7;
    display: block;
    margin-top: 2px;
  }

  #globo-filter-panel .gfp-body { padding: 14px 18px 18px; }

  #globo-filter-panel .gfp-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 10px 0;
    border-bottom: 1px solid #f0f0f0;
  }
  #globo-filter-panel .gfp-row:last-child { border-bottom: none; }

  #globo-filter-panel .gfp-label {
    font-size: 13.5px;
    font-weight: 600;
    color: #1a1a2e;
    line-height: 1.3;
  }
  #globo-filter-panel .gfp-sublabel {
    font-size: 11px;
    color: #888;
    font-weight: 400;
    margin-top: 2px;
  }

  /* Toggle switch */
  .gfp-toggle { position: relative; width: 44px; height: 24px; flex-shrink: 0; }
  .gfp-toggle input { opacity: 0; width: 0; height: 0; }
  .gfp-toggle .gfp-slider {
    position: absolute; inset: 0;
    background: #ccc;
    border-radius: 24px;
    cursor: pointer;
    transition: background 0.2s;
  }
  .gfp-toggle .gfp-slider:before {
    content: '';
    position: absolute;
    height: 18px; width: 18px;
    left: 3px; bottom: 3px;
    background: white;
    border-radius: 50%;
    transition: transform 0.2s;
    box-shadow: 0 1px 4px rgba(0,0,0,0.18);
  }
  .gfp-toggle input:checked + .gfp-slider { background: #e02020; }
  .gfp-toggle input:checked + .gfp-slider:before { transform: translateX(20px); }
`;
document.head.appendChild(style);

// --- Helper: read/write prefs ---
function getPrefs() {
  try { return JSON.parse(localStorage.getItem('globoFilterPrefs') || '{}'); } catch(e) { return {}; }
}
function savePrefs(p) {
  localStorage.setItem('globoFilterPrefs', JSON.stringify(p));
}

// --- Apply filters based on stored prefs ---
function applyFilters() {
  const p = getPrefs();

  // 1. Entretenimento column
  const entCol = document.getElementById('coluna-entretenimento');
  if (entCol) {
    entCol.style.display = p.hideEntretenimento ? 'none' : '';
    // Also hide the hr separators surrounding the entertainment column
    const hrBefore = entCol.previousElementSibling;
    if (hrBefore && hrBefore.tagName === 'HR') hrBefore.style.display = p.hideEntretenimento ? 'none' : '';
    const hrAfter = entCol.nextElementSibling;
    if (hrAfter && hrAfter.tagName === 'HR') hrAfter.style.display = p.hideEntretenimento ? 'none' : '';
  }

  // Also hide the entertainment column's "Mais Entretenimento" button area
  const maisEnt = document.querySelector('.more-container a[data-tracking-action*="mais-entretenimento"]');
  if (maisEnt) {
    const container = maisEnt.closest('.more-container');
    if (container) container.style.display = p.hideEntretenimento ? 'none' : '';
  }

  // Hide post-column-2 in the destaque (top-right entertainment block)
  const destaqueEntCol = document.querySelector('.post-column-2');
  if (destaqueEntCol) destaqueEntCol.style.display = p.hideEntretenimento ? 'none' : '';

  // 2. Horoscope widget
  const horoscopoWidget = document.querySelector('.widget-horoscopo');
  if (horoscopoWidget) horoscopoWidget.style.display = p.hideHoroscopo ? 'none' : '';

  // 3. Celebrity gossip: hide articles tagged as "entretenimento" in the trilho and inline listings
  // The trilho item with celebrity gossip sources (revistaquem, extra famosos, marieclaire celebridades)
  const gossipSources = ['revistaquem.globo.com', 'extra.globo.com/famosos', 'revistamarieclaire.globo.com/celebridades'];
  const allTrilhoItems = document.querySelectorAll('.destaque-trilho li.post');
  allTrilhoItems.forEach(function(item) {
    const link = item.querySelector('a, [data-mrf-link]');
    const href = (link && (link.href || link.getAttribute('data-mrf-link'))) || '';
    const isGossip = gossipSources.some(function(src) { return href.indexOf(src) !== -1; });
    if (isGossip) item.style.display = p.hideGossip ? 'none' : '';
  });

  // Hide wrappers in entertainment column with celebrity/gossip editorial labels
  const gossipLabels = ['Famosos', 'Celebridades', 'Filhos dos Famosos', 'Notícias'];
  const gossipProducts = ['Extra', 'Quem', 'Marie Claire'];
  const allWrappers = document.querySelectorAll('#coluna-entretenimento .wrapper');
  allWrappers.forEach(function(wrapper) {
    const editorial = wrapper.querySelector('.post__source--editorial');
    const product = wrapper.querySelector('.post__source--product');
    const editText = editorial ? editorial.textContent.trim() : '';
    const prodText = product ? product.textContent.trim() : '';
    const isGossip = gossipLabels.indexOf(editText) !== -1 || gossipProducts.indexOf(prodText) !== -1;
    if (isGossip) wrapper.style.display = p.hideGossip ? 'none' : '';
  });
}

// --- Panel HTML ---
const panel = document.createElement('div');
panel.id = 'globo-filter-panel';
panel.innerHTML = `
  <div class="gfp-header">
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3"/></svg>
    <span>Filtros de Conteúdo<small>Globo.com — personalização</small></span>
  </div>
  <div class="gfp-body">
    <div class="gfp-row">
      <div>
        <div class="gfp-label">📺 Coluna Entretenimento</div>
        <div class="gfp-sublabel">Oculta a seção "Entretenimento" completa</div>
      </div>
      <label class="gfp-toggle">
        <input type="checkbox" id="gfp-toggle-entretenimento">
        <span class="gfp-slider"></span>
      </label>
    </div>
    <div class="gfp-row">
      <div>
        <div class="gfp-label">🔮 Widget Horóscopo</div>
        <div class="gfp-sublabel">Remove o widget de signos e horóscopo</div>
      </div>
      <label class="gfp-toggle">
        <input type="checkbox" id="gfp-toggle-horoscopo">
        <span class="gfp-slider"></span>
      </label>
    </div>
    <div class="gfp-row">
      <div>
        <div class="gfp-label">🌟 Fofoca de Celebridades</div>
        <div class="gfp-sublabel">Oculta notícias de famosos (Quem, Extra, Marie Claire…)</div>
      </div>
      <label class="gfp-toggle">
        <input type="checkbox" id="gfp-toggle-gossip">
        <span class="gfp-slider"></span>
      </label>
    </div>
  </div>
`;
document.body.appendChild(panel);

// --- FAB button ---
const btn = document.createElement('button');
btn.id = 'globo-filter-btn';
btn.innerHTML = `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3"/></svg> Filtros`;
document.body.appendChild(btn);

// --- Restore toggle states from prefs ---
const prefs = getPrefs();
const togEnt = document.getElementById('gfp-toggle-entretenimento');
const togHoro = document.getElementById('gfp-toggle-horoscopo');
const togGossip = document.getElementById('gfp-toggle-gossip');
if (togEnt) togEnt.checked = !!prefs.hideEntretenimento;
if (togHoro) togHoro.checked = !!prefs.hideHoroscopo;
if (togGossip) togGossip.checked = !!prefs.hideGossip;

// --- Wire up toggle events ---
function wireToggle(id, key) {
  const el = document.getElementById(id);
  if (!el) return;
  el.addEventListener('change', function() {
    const p = getPrefs();
    p[key] = el.checked;
    savePrefs(p);
    applyFilters();
  });
}
wireToggle('gfp-toggle-entretenimento', 'hideEntretenimento');
wireToggle('gfp-toggle-horoscopo', 'hideHoroscopo');
wireToggle('gfp-toggle-gossip', 'hideGossip');

// --- Toggle panel open/close ---
btn.addEventListener('click', function() {
  panel.classList.toggle('open');
});

// Close panel when clicking outside
document.addEventListener('click', function(e) {
  if (!panel.contains(e.target) && e.target !== btn && !btn.contains(e.target)) {
    panel.classList.remove('open');
  }
});

// Apply on load
applyFilters();

